async function resolveApiKey(ctx) {
    const connection = await ctx.integration?.connection?.active?.(PROVIDER_ID);
    if (connection) {
        const credential = await ctx.integration?.connection?.resolve?.(connection);
        if (credential?.type === "key" && credential.key) {
            return credential.key;
        }
    }
    if (process.env.RACE_CONTROL_API_KEY)
        return process.env.RACE_CONTROL_API_KEY;
    const config = await ctx.client?.config?.get?.();
    return config?.data?.provider?.[PROVIDER_ID]?.options?.apiKey;
