// requestImage never logs the prompt or response body; only the HTTP status is
// surfaced on failure.
async function requestImage(baseURL, apiKey, prompt, size, signal) {
    const response = await fetch(`${baseURL}/images/generations`, {
        method: "POST",
        headers: {
            "content-type": "application/json",
            authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({ prompt, ...(size ? { size } : {}) }),
        signal,
    });
    if (!response.ok) {
        throw new Error(`Race Control image request failed with status ${response.status}`);
    }
    const payload = (await response.json());
    const first = payload.data?.[0];
    if (!first) {
        throw new Error("Race Control image request returned no image data");
    }
    if (first.b64_json) {
        return Buffer.from(first.b64_json, "base64");
    }
    if (first.url) {
        const download = await fetch(first.url, { signal });
        if (!download.ok) {
            throw new Error(`Race Control image download failed with status ${download.status}`);
        }
        return Buffer.from(await download.arrayBuffer());
    }
    throw new Error("Race Control image request returned an unsupported payload");
}
// imageExtension sniffs the container so a fallback provider that emits JPEG
// or WebP is not mislabeled as PNG.
function imageExtension(image) {
    if (image.length >= 8 &&
        image[0] === 0x89 &&
        image[1] === 0x50 &&
        image[2] === 0x4e &&
        image[3] === 0x47) {
        return "png";
    }
    if (image.length >= 2 && image[0] === 0xff && image[1] === 0xd8) {
        return "jpeg";
    }
    if (image.length >= 12 &&
        image[8] === 0x57 &&
        image[9] === 0x45 &&
        image[10] === 0x42 &&
        image[11] === 0x50) {
        return "webp";
    }
    return "png";
}
